-- ############################################################
-- SECCIÓN 2 - DML (datos de prueba)
-- ############################################################

-- ============================================================
-- Little Horizons ERP - Datos de prueba (DML)
-- Base de datos: erp_little_horizons   |   Motor: MySQL 8.0.16 o superior
-- ============================================================
-- Fecha de referencia del conjunto de datos: 10 de noviembre de 2026.
-- Año académico en curso: 2026 (calendario A). Períodos: I (19-ene a 27-mar), II (6-abr a 12-jun),
-- III (6-jul a 11-sep) y IV (14-sep a 20-nov, en curso: sin notas registradas todavía).
--
-- CRITERIOS DE COHERENCIA APLICADOS
--  * Género coherente con el nombre; apellidos de hermanos iguales; padres con apellidos coherentes.
--  * Documento según edad: RC (menor de 7 años), TI (7 a 17), CC (18 o más); CE y Pasaporte para extranjeros.
--  * Edad coherente con el grado (4 estudiantes por grado, de Preescolar a Once).
--  * Cada estudiante tiene al menos un acudiente; hay familias con hermanos (acudientes con varios hijos).
--  * Cada materia pertenece a un grado; los ids de grado son id_grado = nivel_numerico + 1
--    (Preescolar = 1, Primero = 2, ..., Once = 12).
--  * Inscripciones solo en materias del grado del estudiante y de su sección (7° y 11° tienen secciones A y B).
--  * Las notas solo existen para materias inscritas y las registra el profesor asignado a esa materia y sección.
--  * Las notas 2025 (períodos I a IV y Final) solo se cargaron para 6 estudiantes piloto (4 vigentes y los
--    2 graduados de la promoción 2025); en 2026 todos tienen notas de los períodos I, II y III.
--    La nota 'Final' 2025 es el promedio de los períodos I a IV con un decimal.
--  * Asistencia: registro diario de 2 materias troncales (Matemáticas y Lengua Castellana; en Preescolar,
--    Pensamiento Lógico y Lenguaje y Comunicación) entre el 26-oct y el 6-nov-2026 (sin festivo 2-nov).
--  * Pagos: montos coherentes con el catálogo de conceptos; descuentos documentados en la columna notas.
--  * Facturas: una por pago. CUFE = SHA-384 (hex) de numero_factura + NIT + fecha_emision (AAAA-MM-DD),
--    con NIT ficticio 900123456-8. Los archivos TXT no se incluyen: nombre_archivo y ruta_archivo quedan en NULL.
--  * Recursos: el estado del recurso es coherente con sus préstamos (Prestado solo si hay un préstamo sin devolver)
--    y no existen préstamos simultáneos del mismo recurso. Eventos con posiciones solo si tienen competencia.
--  * Clubes: cupos respetados (solo membresías Activas cuentan para el cupo).
--
-- CASOS DE PRUEBA INCLUIDOS (ids de estudiante)
--  * Morosos (sin pago de pensión en los últimos 30 días): 18, 26, 38, 46
--  * Hermanos vigentes (grupos por familia): (1, 29); (5, 13, 37); (9, 25); (10, 22); (14, 45); (17, 33); (21, 41); (26, 38)
--  * Inasistencia > 3 en una semana: 27 (4 ausencias, semana del 26-oct), 39 (4 ausencias por
--    suspensión, semana del 3-nov); con Excusa Médica 4 días: 43; con 4 tardanzas: 15
--  * Estudiante retirado: 34. Estudiante suspendido: 39. Graduados 2025: 49 y 50.
--  * Préstamos vencidos (id_recurso, id_estudiante): (11, 22), (3, 30), (39, 45), (28, 42), (36, 30) ; a profesores (id_recurso, id_profesor): (46, 25), (18, 35)
--  * Clubes llenos: Club de Robótica (id 17) y Club de Natación (id 4). Club inactivo: Club de Cine (id 28).
--  * Eventos futuros con inscritos y sin posiciones: Torneo de Natación Institucional (competencia).
-- ============================================================

USE erp_little_horizons;
SET NAMES utf8mb4;


